import os
import time
from typing import Any, Dict, Optional, TypeVar, Callable

import requests


# Retry configuration
MAX_RETRIES = 3
RETRY_DELAY_SECONDS = 1.0
RETRY_BACKOFF_MULTIPLIER = 2.0

T = TypeVar("T")

# Cached session for connection reuse
_session: Optional[requests.Session] = None


def _get_session() -> requests.Session:
    """Get or create a cached requests session for connection reuse."""
    global _session
    if _session is None:
        _session = requests.Session()
    return _session


def _with_retry(func: Callable[[], T], operation_name: str) -> T:
    """Execute a function with exponential backoff retry on transient errors."""
    last_exception: Exception | None = None
    delay = RETRY_DELAY_SECONDS

    for attempt in range(MAX_RETRIES):
        try:
            return func()
        except requests.exceptions.Timeout as e:
            last_exception = e
            print(f"[db] {operation_name} timeout (attempt {attempt + 1}/{MAX_RETRIES})")
        except requests.exceptions.ConnectionError as e:
            last_exception = e
            print(f"[db] {operation_name} connection error (attempt {attempt + 1}/{MAX_RETRIES})")
        except requests.exceptions.HTTPError as e:
            # Only retry on 5xx server errors
            if e.response is not None and 500 <= e.response.status_code < 600:
                last_exception = e
                print(f"[db] {operation_name} server error {e.response.status_code} (attempt {attempt + 1}/{MAX_RETRIES})")
            else:
                raise  # Don't retry client errors

        if attempt < MAX_RETRIES - 1:
            time.sleep(delay)
            delay *= RETRY_BACKOFF_MULTIPLIER

    raise RuntimeError(f"{operation_name} failed after {MAX_RETRIES} attempts") from last_exception


def _supabase_url() -> str:
    url = os.environ.get("SUPABASE_URL")
    if not url:
        raise RuntimeError("SUPABASE_URL not set")
    return url.rstrip("/")


def _headers() -> dict:
    key = os.environ.get("SUPABASE_SERVICE_ROLE_KEY")
    if not key:
        raise RuntimeError("SUPABASE_SERVICE_ROLE_KEY not set")
    return {
        "Authorization": f"Bearer {key}",
        "apikey": key,
        "Content-Type": "application/json",
        "Prefer": "return=minimal",
    }


